import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label, FormGroup } from 'reactstrap';
import Select from 'react-select';
import validator from 'validator';
import CustomButton from '../../../../components/CustomButton';
import { employeeStatic } from '../../../../config/constants';
import { formEmpSelectList, formResMessage } from 'utils/commonFunc';
import SubjectPicker from 'views/admin/Common/SubjectPicker.jsx';

const EmpSubjectAssignModal = ({
  isSubAssignModalOpen,
  formModalCloseProp,
  employees,
  // subjects,
  saveAssignSubject,
  empAssignSubject,
  updateAssignSubject,
  assignSubjectSuccess,
  employeeId,
  unAssignedSubjectList,
}) => {
  const stateObj = {
    data: {
      employeeId: '',
      schoolId: 0,
      subjects: [],
    },
    edit: false,
    assignedSubjectsArr: [],
    empArr: [],
    subArr: [],
    errors: {},
    loading: false,
  };

  const [stateVal, setState] = useState(stateObj);
  const [subjectSearchText, setSubjectSearchText] = useState('');

  useEffect(() => {
    let assignSubArr = [];
    if (empAssignSubject?.length > 0) {
      assignSubArr = empAssignSubject.map(item => {
        return {
          subjectId: item.subjectId,
          label: `${item.name} (${item.course.name})`,
          value: item.subjectId,
          teacherSubjectId: item.teacherSubjectId,
        };
      });
    }
    setState(prevState => ({
      ...prevState,
      edit: true,
      assignedSubjectsArr: assignSubArr,
      data: {
        ...prevState.data,
        employeeId,
        schoolId: 0,
        subjects: assignSubArr,
      },
    }));
  }, [employeeId, empAssignSubject]);

  const handleSelectChange = (name, selectItem) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: selectItem || [],
      },
    }));
  };

  // Computes the next subjects list off prevState rather than `data.subjects` in scope, so
  // "Select all shown below" - which calls this once per subject, synchronously, before any
  // of them re-render - accumulates correctly instead of each call clobbering the last.
  const toggleSubject = (sub, checked) => {
    setState(prevState => {
      const currentSubjects = prevState.data.subjects || [];
      const nextSubjects = checked
        ? [...currentSubjects, sub]
        : currentSubjects.filter(el => el.subjectId !== sub.subjectId);
      return { ...prevState, data: { ...prevState.data, subjects: nextSubjects } };
    });
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data, assignedSubjectsArr } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (!Object.keys(errors).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      if (stateVal.edit) {
        updateAssignSubject(data, assignedSubjectsArr)
          .then(() => {
            stateReset();
            assignSubjectSuccess('update');
          })
          .catch(err => setError(err));
      } else {
        saveAssignSubject(data)
          .then(() => {
            stateReset();
            assignSubjectSuccess('add');
          })
          .catch(err => setError(err));
      }
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateReset();
    formModalCloseProp();
  };

  const validate = data => {
    const errors = {};
    if (validator.isEmpty(data.employeeId.toString())) {
      errors.employeeId = `${employeeStatic} cannot be empty`;
    }
    if (!data.subjects?.length) {
      errors.subjectId = 'Subject cannot be empty';
    }
    return errors;
  };

  const { edit, data, errors, loading } = stateVal;

  const empArr = formEmpSelectList(employees);
  const subjectOptions = (unAssignedSubjectList || []).map(item => ({
    subjectId: item.subjectId,
    label: `${item.name} (${item.course.name})`,
    groupLabel: item.course.name,
  }));

  const thisData = (
    <Modal size="lg" isOpen={isSubAssignModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>
          {edit ? `UPDATE ${employeeStatic.toUpperCase()} SUBJECT` : `ASSIGN ${employeeStatic.toUpperCase()} SUBJECT`}
        </ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              <Row>
                <Col sm={12}>
                  <FormGroup>
                    <Label htmlFor="">
                      {employeeStatic}
                      <sup> *</sup>
                    </Label>
                    <Select
                      value={empArr?.find(dt => dt.employeeId === data.employeeId)}
                      // onChange={value => handleSelectChange('employee', value)}
                      options={empArr}
                      isDisabled={true}
                    />
                    {errors.employeeId && <span className="err-msg">{errors.employeeId}</span>}
                  </FormGroup>
                </Col>
                <Col sm={12}>
                  <FormGroup>
                    {/* <Label htmlFor="">
                      Select Subjects<sup> *</sup>
                    </Label> */}
                    <SubjectPicker
                      idKey="subjectId"
                      subjectOptions={subjectOptions}
                      getGroupLabel={sub => sub.groupLabel}
                      searchText={subjectSearchText}
                      onSearchTextChange={setSubjectSearchText}
                      selectedMap={Object.fromEntries((data.subjects || []).map(el => [el.subjectId, el]))}
                      onToggle={toggleSubject}
                      onClearAll={() => handleSelectChange('subjects', [])}
                    />
                    {errors.subjectId && <span className="err-msg">{errors.subjectId}</span>}
                  </FormGroup>
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default EmpSubjectAssignModal;
