import React from 'react';
import { useHistory, useLocation } from 'react-router-dom';
import { Paper, Tab, Tabs } from '@material-ui/core';
import colors from 'config/colors';
import { employeeStatic } from 'config/constants';
import SubjectPage from './SubjectPage';
import TeacherSubjectsPage from '../Employee/TeacherSubjectsPage';

// Subjects and who teaches them are one setup: the subjects of each class, then the teacher of each subject. Two tabs of
// one Subjects page (the tab is in the address: ?tab=teacher-subjects).
const TABS = [
  { key: 'subjects', label: 'Subjects' },
  { key: 'teacher-subjects', label: `${employeeStatic} subjects` },
];

const SubjectsHubPage = () => {
  const history = useHistory();
  const location = useLocation();
  const tabKey = new URLSearchParams(location.search).get('tab');
  const active = Math.max(
    0,
    TABS.findIndex(tab => tab.key === tabKey)
  );

  return (
    <div className="content">
      <Paper square style={{ marginBottom: 20 }}>
        <Tabs
          value={active}
          onChange={(e, index) => history.push(`${location.pathname}?tab=${TABS[index].key}`)}
          indicatorColor=""
          textColor="inherit"
          variant="scrollable"
          scrollButtons="off">
          {TABS.map((tab, index) => (
            <Tab
              key={tab.key}
              label={tab.label}
              style={{
                fontWeight: 'bold',
                minWidth: 140,
                color: active === index ? colors.accent : '',
                borderBottom: active === index ? `3px solid ${colors.accent}` : '3px solid transparent',
              }}
            />
          ))}
        </Tabs>
      </Paper>
      {active === 0 ? <SubjectPage /> : <TeacherSubjectsPage />}
    </div>
  );
};

export default SubjectsHubPage;
