import React from 'react';
import { connect } from 'react-redux';
import { Label, FormGroup } from 'reactstrap';
import { employeeSubAssignHead } from 'variables/general';

import {
  fetchSchoolEmployeesApi,
  saveEmpAssignSubjectService,
  fetchEmpAssignSubjectService,
  updateEmpAssignSubjectService,
  deleteEmpAssignSubjectService,
} from 'actions/admin/employees';
import EmpSubjectAssignModal from './components/EmpSubjectAssignModal.jsx';
import { fetchSchoolSubjectsService, fetchUnAssigedSchoolSubjectsService } from '../../../actions/admin/subjects.js';
import {
  formEmpSelectList,
  formResMessage,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  getLoggedUserUtils,
  makeSubText,
} from '../../../utils/commonFunc.js';
import { store } from '../../../index.js';
import { showToast, fetchUserService } from '../../../actions/admin/auth.js';
import CustomButton from '../../../components/CustomButton.jsx';
import { employeeStatic } from '../../../config/constants.js';
import constants from '../../../config/constants.js';
import MuiTable from '../Common/MuiTable.jsx';
import ConfirmModal from '../Common/ConfirmModal.jsx';
import CustomSelect from 'components/CustomSelect.jsx';
import EmptyState from '../Common/EmptyState.jsx';
import CommonTooltip from '../Common/CommonTooltip.jsx';
import PersonOutlineIcon from '@material-ui/icons/PersonOutline';
import MenuBookIcon from '@material-ui/icons/MenuBook';
import colors from '../../../config/colors';

// What used to be the "Assigned Subjects" tab on the old Teachers page (views/admin/Employee/
// EmployeePage.jsx) - the "ALL TEACHERS" list itself moved to School Staffs (see
// views/admin/SchoolStaff/), leaving this page scoped purely to subject assignment. A teacher
// viewing this sees only their own assignments, read-only; an admin still gets the full picker
// and can modify any teacher's assignments, same as before.
class TeacherSubjectsPage extends React.Component {
  state = {
    schoolId: 0,
    employeeId: null,
    // Fetched into local state, not the shared state.employees.employeeList redux slice -
    // Staff Attendance/School Staffs/Reports etc. all write into that same slot with whatever
    // profession (TEACHING/NON_TEACHING) they last fetched, so reading it here after visiting
    // one of those pages could silently show workers in what's meant to be a teachers-only list.
    employeeList: [],
    isSubAssignModalOpen: false,
    confirmModalOpen: false,
    fetchError: '',
    // Starts true so the first render shows the table's loading skeleton instead of the
    // "No subjects assigned yet" empty state - empAssignSubject comes straight from redux with
    // no fetch-in-progress flag of its own, so length===0 is indistinguishable from "not fetched
    // yet" unless this tracks it separately.
    isLoading: true,
  };

  isViewingSelf = () => this.props.loggedUserRole === constants.roles.teacher;

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (!globalSchool) {
      this.showWarning('Please select School', 'warning');
      return;
    }
    this.setState({ schoolId: globalSchool.schoolId }, () => {
      if (this.isViewingSelf()) {
        const employeeId = this.props.loggedUserId;
        this.setState({ employeeId }, () => this.fetchEmpAssignSubjectsApi(employeeId));
        if (!this.props.userProfile?.employeeId) {
          this.props.fetchUser({
            userRole: constants.roles.teacher,
            userId: employeeId,
            token: this.props.loggedUserToken,
          });
        }
      } else {
        this.fetchSchoolEmployees();
      }
    });
  }

  fetchSchoolEmployees = async refetchAgain => {
    let empList = this.state.employeeList;
    if (!empList.length || refetchAgain) {
      empList =
        (await fetchSchoolEmployeesApi({
          schoolId: this.state.schoolId,
          token: this.props.loggedUserToken,
          profession: 'TEACHING',
        })) || [];
      this.setState({ employeeList: empList });
    }
    const employeeId = this.state.employeeId || empList?.[0]?.employeeId;
    if (employeeId) {
      this.fetchEmpAssignSubjectsApi(employeeId);
      !this.state.employeeId && this.setState({ employeeId });
    } else {
      // No teachers at all - fetchEmpAssignSubjectsApi (the only other place isLoading gets
      // cleared) never gets called, so nothing else will end the loading state.
      this.setState({ isLoading: false });
    }
  };

  fetchSchoolSubjects = () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (!this.props.subjects.length) {
      this.props.fetchSchoolSubjects({ schoolId: this.state.schoolId, batchId, token: this.props.loggedUserToken });
    }
  };

  fetchAllSubjects = refetchAgain => {
    const { batchId } = getGlobalCurrentBatchUtils();
    this.fetchSchoolSubjects();
    if (batchId && (!this.props.unAssignedSubjectList?.length || refetchAgain)) {
      this.props.fetchUnAssigedSchoolSubjects({
        schoolId: this.state.schoolId,
        batchId,
        token: this.props.loggedUserToken,
      });
    }
  };

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  fetchEmpAssignSubjectsApi = async (employeeId, refetchAgain) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (
      (batchId && employeeId && employeeId !== this.state.employeeId) ||
      !this.props.empSubjectList?.length ||
      refetchAgain
    ) {
      this.setState({ isLoading: true });
      try {
        await this.props.fetchEmpAssignSubject({ batchId, employeeId, token: this.props.loggedUserToken });
        this.setState({ fetchError: '' });
      } catch (err) {
        // Render the page empty rather than letting an unhandled rejection break the whole
        // screen - the actual API error is surfaced above the (now empty) table.
        this.setState({ fetchError: formResMessage(err) });
      } finally {
        this.setState({ isLoading: false });
      }
    } else {
      this.setState({ isLoading: false });
    }
  };

  handleSelectChange = sItem => {
    if (sItem.value !== this.state.employeeId) {
      this.fetchEmpAssignSubjectsApi(sItem.value, true);
      this.setState({ employeeId: sItem.value });
    }
  };

  subAssignFormModalOpen = () => {
    this.fetchAllSubjects();
    this.fetchEmpAssignSubjectsApi(this.state.employeeId);
    this.setState({ isSubAssignModalOpen: true });
  };

  subAssignFormModalClose = () => this.setState({ isSubAssignModalOpen: false });

  saveAssignSubject = data => {
    return this.props.saveAssignSubject({ postData: data, token: this.props.loggedUserToken });
  };

  updateAssignSubject = (data, prevAssignArr) => {
    data.schoolId = this.state.schoolId;
    return this.props.updateAssignSubject({ postData: data, token: this.props.loggedUserToken }).then(() => {
      prevAssignArr.forEach((item, i) => {
        const lIndex = prevAssignArr.length === i + 1;
        const delIndex = data.subjects.findIndex(d => d.subjectId === item.subjectId);
        if (delIndex < 0) {
          this.deleteEmpAssignSubject(item.teacherSubjectId, lIndex);
        }
      });
    });
  };

  assignSubjectSuccess = actionParam => {
    this.setState({ isSubAssignModalOpen: false });
    this.showWarning(
      actionParam === 'add' ? 'Subject assigned successfully' : 'Subject assign updated successfully',
      'success'
    );
    this.fetchEmpAssignSubjectsApi(this.state.employeeId, true);
    this.fetchAllSubjects(true);
  };

  deleteConfirmEmpAssignSubject = () => {
    const { empAssignSubject } = this.props;
    if (empAssignSubject?.length > 0) {
      empAssignSubject.forEach(async (item, i) => {
        const lIndex = empAssignSubject.length === i + 1;
        await this.deleteEmpAssignSubject(item.teacherSubjectId, lIndex);
      });
    }
  };

  deleteEmpAssignSubject = async (teacherSubjectId, lIndex) => {
    await this.props
      .deleteEmpAssignSubject({ teacherSubjectId, token: this.props.loggedUserToken })
      .then(() => {
        if (lIndex) {
          this.fetchEmpAssignSubjectsApi(this.state.employeeId, true);
          this.fetchAllSubjects(true);
          this.setState({ isSubAssignModalOpen: false });
        }
      })
      .catch(err => this.showWarning(formResMessage(err), 'error'));
  };

  openDeleteConfirmModal = async () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    await this.props.fetchEmpAssignSubject({
      batchId,
      employeeId: this.state.employeeId,
      token: this.props.loggedUserToken,
    });
    this.setState({ confirmModalOpen: true });
  };

  deleteConfirm = () => this.deleteConfirmEmpAssignSubject();

  render() {
    const { employeeId, employeeList, isSubAssignModalOpen, confirmModalOpen, fetchError, isLoading } = this.state;
    const { subjects, empAssignSubject, unAssignedSubjectList, userProfile } = this.props;
    const viewingSelf = this.isViewingSelf();
    const empArr = formEmpSelectList(employeeList);
    const selfName = userProfile?.name || getLoggedUserUtils()?.fullName || 'You';
    const selfCode = userProfile?.code;

    const subjectAssignDiv =
      !isLoading && empAssignSubject.length === 0 ? (
        <EmptyState
          icon={<MenuBookIcon style={{ color: colors.accent, fontSize: 30 }} />}
          title={viewingSelf ? 'No subjects assigned to you yet' : 'No subjects assigned yet'}
          subtitle={
            fetchError ||
            (viewingSelf
              ? "Once your school admin assigns you a subject, it'll show up here."
              : `Pick a ${employeeStatic.toLowerCase()} above, or assign one via "Modify Assigned Subject".`)
          }
        />
      ) : (
        <MuiTable
          tableHeaders={employeeSubAssignHead}
          tableBodyData={{
            content: isLoading
              ? []
              : empAssignSubject.map(el => ({
                  subjectCode: el?.subjectCode,
                  name: (
                    <>
                      {el?.name} {makeSubText(el?.subjectCode)}
                    </>
                  ),
                  courseCode: el?.course?.code,
                  courseName: (
                    <>
                      {el?.course?.name} {makeSubText(el?.course?.code)}
                    </>
                  ),
                })),
          }}
          bodyColumns={['name', 'courseName']}
          idName="subjectId"
          hidePagination={true}
          isLoading={isLoading}
        />
      );

    return (
      <div className="content">
        {viewingSelf ? (
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 10,
              backgroundColor: `${colors.accent}0a`,
              border: `1px solid ${colors.accent}1f`,
              borderRadius: 10,
              padding: '10px 16px',
              marginBottom: 16,
            }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <PersonOutlineIcon style={{ color: colors.accent }} />
              <span style={{ fontSize: 13, color: colors.grey2 }}>
                Viewing subjects for <b style={{ color: colors.grey1 }}>{selfName}</b>
                {selfCode ? ` (${selfCode})` : ''}
              </span>
            </div>
            <CommonTooltip content="Only school-admin can update this">
              <span>
                <CustomButton
                  style={{ opacity: 0.5, cursor: 'not-allowed' }}
                  onClick={() => this.showWarning('Only school-admin can update this', 'warning')}
                  name={empAssignSubject.length > 0 ? 'Modify Assigned Subjects' : 'Assign Subject'}
                />
              </span>
            </CommonTooltip>
          </div>
        ) : (
          <div
            style={{
              display: 'flex',
              alignItems: 'flex-end',
              justifyContent: 'space-between',
              flexWrap: 'wrap',
              gap: 12,
              marginBottom: 8,
            }}>
            <div style={{ flex: '0 1 320px' }}>
              <FormGroup className="mb-0">
                <Label htmlFor="">
                  <strong>
                    {employeeStatic}
                    <sup> *</sup>
                  </strong>
                </Label>
                <CustomSelect
                  name="employeeId"
                  noLabel={true}
                  value={employeeId}
                  onChange={(name, value) => this.handleSelectChange({ value })}
                  options={empArr}
                  applyLabelStyle={true}
                />
              </FormGroup>
            </div>
            <CustomButton
              disabled={isLoading}
              onClick={this.subAssignFormModalOpen}
              name={empAssignSubject.length > 0 ? 'Modify Assigned Subjects' : 'Assign Subject'}
            />
          </div>
        )}
        {!!fetchError && empAssignSubject.length > 0 && (
          <div
            style={{
              color: '#a94442',
              backgroundColor: '#fdecea',
              padding: '10px 14px',
              borderRadius: 6,
              marginBottom: 12,
              fontSize: 13,
            }}>
            {fetchError}
          </div>
        )}
        {subjectAssignDiv}
        {!viewingSelf && (
          <>
            <EmpSubjectAssignModal
              employeeId={employeeId}
              isSubAssignModalOpen={isSubAssignModalOpen}
              formModalCloseProp={this.subAssignFormModalClose}
              employees={employeeList}
              subjects={subjects}
              saveAssignSubject={this.saveAssignSubject}
              empAssignSubject={empAssignSubject}
              updateAssignSubject={this.updateAssignSubject}
              assignSubjectSuccess={this.assignSubjectSuccess}
              unAssignedSubjectList={unAssignedSubjectList}
            />
            <ConfirmModal
              confirmModalOpen={confirmModalOpen}
              deleteConfirm={this.deleteConfirm}
              deleteCancel={() => this.setState({ confirmModalOpen: false })}
            />
          </>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => ({
  loggedUserId: state.auth.loggedUserId,
  loggedUserToken: state.auth.loggedUserToken,
  loggedUserRole: state.auth.loggedUserRole,
  subjects: state.subjects.subjectList,
  empAssignSubject: state.employees.empAssignSubject,
  unAssignedSubjectList: state.subjects.unAssignedSubjectList || [],
  userProfile: state.auth.userProfile,
});

const mapDispatchToProps = dispatch => ({
  fetchSchoolSubjects: data => dispatch(fetchSchoolSubjectsService(data)),
  saveAssignSubject: data => dispatch(saveEmpAssignSubjectService(data)),
  fetchEmpAssignSubject: data => dispatch(fetchEmpAssignSubjectService(data)),
  updateAssignSubject: data => dispatch(updateEmpAssignSubjectService(data)),
  deleteEmpAssignSubject: data => dispatch(deleteEmpAssignSubjectService(data)),
  fetchUnAssigedSchoolSubjects: data => dispatch(fetchUnAssigedSchoolSubjectsService(data)),
  fetchUser: data => dispatch(fetchUserService(data)),
});

export default connect(mapStateToProps, mapDispatchToProps)(TeacherSubjectsPage);
